"""
Reescribe completos, en tu copia local (voice_control_repo), los archivos del
cambio de aprendizaje pasivo + servidor web para el telefono. Sobrescribe cada
archivo con su version final (no es un parche parcial, evita cualquier problema
de coincidencia de texto).

Uso:
    python aplicar_telefono_aprendizaje.py

Luego:
    git add -A
    git commit -m "Alfred aprende solo del vault y se puede usar por voz desde el telefono"
    git push
"""
import base64
from pathlib import Path

BASE = Path(__file__).parent

ARCHIVOS = {
    "asistente.py": "",
    "obsidian_vault.py": "",
    "servidor_web.py": "",
    "requirements.txt": "YW50aHJvcGljCnNvdW5kZGV2aWNlCnNvdW5kZmlsZQpzY2lweQpudW1weQplZGdlLXR0cwpwbGF5c291bmQzCnBsYXl3cmlnaHQKcHl0dHN4MwpweWNhdwpjb210eXBlcwp3bWkKcHl3aW4zMgpweWF1dG9ndWkKcGlsbG93CmZhc3RhcGkKdXZpY29ybltzdGFuZGFyZF0K",
    ".env.example": "",
    "ALFRED_TELEFONO.md": "",
}

for nombre, b64 in ARCHIVOS.items():
    ruta = BASE / nombre
    ruta.parent.mkdir(parents=True, exist_ok=True)
    ruta.write_bytes(base64.b64decode(b64))
    print(f"✅ Escrito {nombre}")

print("\nListo. Ahora: git add -A && git commit -m \"...\" && git push")